/bin/bash -lc "python - <<'PY'
import urllib.request, json
for pkg in ['phykit']:
    url=f'https://quay.io/api/v1/repository/biocontainers/{pkg}/tag/?limit=20'
    try:
        data=json.load(urllib.request.urlopen(url, timeout=20))
        print(pkg)
        for t in data.get('tags',[])[:10]: print(t.get('name'))
    except Exception as e:
        print('ERR', pkg, type(e).__name__, e)
PY"

