import urllib.request
urls=[
 'https://raw.githubusercontent.com/JLSteenwyk/PhyKIT/master/README.md',
 'https://raw.githubusercontent.com/JLSteenwyk/PhyKIT/main/README.md',
 'https://raw.githubusercontent.com/JLSteenwyk/PhyKIT/master/docs/phylogenetic_tree_based/index.md'
]
for url in urls:
 try:
  data=urllib.request.urlopen(url,timeout=20).read().decode('utf-8','replace')
  print('URL',url,'LEN',len(data),'evo_rate?', 'evo_rate' in data or 'evolutionary' in data.lower())
  if 'evo_rate' in data:
   i=data.index('evo_rate'); print(data[max(0,i-500):i+1000])
 except Exception as e: print('ERR',url,type(e).__name__,e)
PY"

